svg.script:
(function () {
  if (typeof gsap === "undefined") return;
  if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

  function flow(selector, dash, distance, duration) {
    var els = gsap.utils.toArray(selector);
    if (!els.length) return;
    gsap.set(els, { attr: { "stroke-dasharray": dash, "stroke-dashoffset": 0 } });
    gsap.to(els, {
      attr: { "stroke-dashoffset": -distance },
      duration: duration,
      ease: "none",
      repeat: -1
    });
  }

  flow(
    "#edge-1,#edge-2,#edge-3,#edge-4,#edge-5,#edge-6,#edge-7,#edge-8,#edge-9,#edge-corrections",
    "7 6", 13, 0.65
  );
  flow("#edge-poll,#edge-deploy-a,#edge-deploy-b,#edge-deploy-c", "5 5", 10, 1.6);
})();
